// Store event in static data (persistent across executions in n8n)
const staticData = $getWorkflowStaticData('global');

if (!staticData.events) staticData.events = [];
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.dailyStats) staticData.dailyStats = {};

const event = $input.first().json.body || $input.first().json;
const today = new Date().toISOString().split('T')[0];

// Store event (keep last 5000)
staticData.events.push({
  ...event,
  receivedAt: new Date().toISOString()
});
if (staticData.events.length > 5000) {
  staticData.events = staticData.events.slice(-5000);
}

// Track session
const sid = event.sessionId || 'unknown';
if (!staticData.sessions[sid]) {
  staticData.sessions[sid] = {
    started: new Date().toISOString(),
    messageCount: 0,
    signals: [],
    pages: []
  };
}
const session = staticData.sessions[sid];
session.messageCount++;
session.lastActivity = new Date().toISOString();
if (event.signal) session.signals.push(event.signal);
if (event.page && !session.pages.includes(event.page)) session.pages.push(event.page);

// Daily stats
if (!staticData.dailyStats[today]) {
  staticData.dailyStats[today] = {
    conversations: 0,
    messages: 0,
    hotSignals: 0,
    warmSignals: 0,
    coldSignals: 0,
    whatsappClicks: 0,
    carteClicks: 0,
    calculateurClicks: 0,
    inputTokens: 0,
    outputTokens: 0
  };
}
const day = staticData.dailyStats[today];
day.messages++;
if (session.messageCount === 1) day.conversations++;
if (event.signal === 'hot') day.hotSignals++;
else if (event.signal === 'warm') day.warmSignals++;
else day.coldSignals++;

// Track button clicks from the event
if (event.userMessage === 'commander_whatsapp') day.whatsappClicks++;
if (event.userMessage === 'voir_carte') day.carteClicks++;
if (event.userMessage === 'voir_calculateur') day.calculateurClicks++;

day.inputTokens += event.inputTokens || 0;
day.outputTokens += event.outputTokens || 0;

// Clean up old sessions (> 24h)
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
for (const [key, sess] of Object.entries(staticData.sessions)) {
  if (new Date(sess.lastActivity || sess.started).getTime() < cutoff) {
    delete staticData.sessions[key];
  }
}

// Clean up old daily stats (keep 90 days)
const oldCutoff = new Date();
oldCutoff.setDate(oldCutoff.getDate() - 90);
for (const dateKey of Object.keys(staticData.dailyStats)) {
  if (new Date(dateKey) < oldCutoff) {
    delete staticData.dailyStats[dateKey];
  }
}

return [{ json: { status: 'stored', today: day } }];

// Read analytics data from static storage
const staticData = $getWorkflowStaticData('global');
const query = $input.first().json.query || {};
const range = query.range || '7d';

// Calculate date range
const now = new Date();
let daysBack = 7;
if (range === '30d') daysBack = 30;
if (range === '90d') daysBack = 90;
if (range === 'today') daysBack = 0;

const startDate = new Date();
startDate.setDate(startDate.getDate() - daysBack);
const startStr = startDate.toISOString().split('T')[0];

// Aggregate daily stats
const dailyStats = staticData.dailyStats || {};
const filteredDays = Object.entries(dailyStats)
  .filter(([date]) => date >= startStr)
  .sort(([a], [b]) => a.localeCompare(b));

// Totals
const totals = {
  conversations: 0,
  messages: 0,
  hotSignals: 0,
  warmSignals: 0,
  coldSignals: 0,
  whatsappClicks: 0,
  carteClicks: 0,
  calculateurClicks: 0,
  inputTokens: 0,
  outputTokens: 0
};

filteredDays.forEach(([, day]) => {
  for (const key of Object.keys(totals)) {
    totals[key] += day[key] || 0;
  }
});

// Active sessions
const activeSessions = Object.values(staticData.sessions || {}).length;

// Recent events (last 50)
const recentEvents = (staticData.events || []).slice(-50).reverse();

// Conversion rate
const conversionRate = totals.conversations > 0
  ? Math.round((totals.hotSignals / totals.conversations) * 100)
  : 0;

// Avg messages per session
const avgMessages = totals.conversations > 0
  ? Math.round((totals.messages / totals.conversations) * 10) / 10
  : 0;

const response = {
  range,
  period: { from: startStr, to: now.toISOString().split('T')[0] },
  totals,
  activeSessions,
  conversionRate,
  avgMessages,
  dailyBreakdown: filteredDays.map(([date, stats]) => ({ date, ...stats })),
  recentEvents: recentEvents.slice(0, 20),
  tokenCost: {
    input: totals.inputTokens,
    output: totals.outputTokens,
    estimatedCostUSD: Math.round((totals.inputTokens * 0.003 + totals.outputTokens * 0.015) / 1000 * 100) / 100
  }
};

return [{ json: response }];
